UNITS = {'mm':.001,'cm':.01,'m':1,'ft':.3048,'us-ft':1200/3937,'fath':1.8288,
         'kmi':1852,'us-ch':79200/3937,'us-mi':6336000/3937,'km':1000,'ind-ft':.30479841,
         'ind-yd':.91439523,'mi':1609.344,'yd':.9144,'ch':20.1168,'link':.201168,
         'dm':.01,'in':.0254,'ind-ch':20.11669506,'us-in':100/3937,'us-yd':3600/3937,
         'rad':1,'deg':DEG,'grad':PI/200}
DATUMS = {'WGS84':('WGS84','towgs84=0,0,0'), 'GGRS87':('GRS80','towgs84=-199.87,74.79,246.62'),
          'NAD83':('GRS80','towgs84=0,0,0'), 'NAD27':('clrk66','nadgrids=@conus,@alaska,@ntv2_0.gsb,@ntv1_can.dat'),
          'potsdam':('bessel','towgs84=606.0,23.0,413.0'), 'carthage':('clrk80ign','towgs84=-263.0,6.0,431.0'),
          'hermannskogel':('bessel','towgs84=653.0,-212.0,449.0'), 'ire65':('mod_airy','towgs84=482.530,-130.596,564.557,-1.042,-0.214,-0.631,8.15'),
          'nzgd49':('intl','towgs84=59.47,-5.04,187.44,0.47,-0.1,1.024,-4.5993'), 'OSGB36':('airy','towgs84=446.448,-125.157,542.06,0.1502,0.247,0.8421,-20.4894')}
PMS = {'greenwich':0,'lisbon':-9.131906111111,'paris':2.337229166667,'bogota':-74.080916666667,
       'madrid':-3.687938888889,'rome':12.452333333333,'bern':7.439583333333,'jakarta':106.807719444444,
