            self.angular_input=False
        if p.get('type')=='crs': self.angular_input=False
        self.a, self.es = self.earth()
        self.e = asqrt(self.es)
        self.one_es = 1 - self.es
        self.b = self.a*math.sqrt(max(0,self.one_es))
        self.lon0 = self.ang('lon_0'); self.lat0 = self.ang('lat_0')
        self.x0 = self.num('x_0'); self.y0 = self.num('y_0')
        self.k0 = self.num('k_0',self.num('k',1))
        self.over = self.has('over'); self.geoc = self.has('geoc')
        self.axis = self.get('axis','enu')
