        self.setup()

    def append(self,t):
        self.tokens.append(t)
        k,_,v=t.partition('=')
        if k not in self.params: self.params[k]=v

    def get(self,k,default=None):
        if k in self.params:
            self.used.add(k)
            return self.params[k]
        return default

    def num(self,k,default=0): return cfloat(self.get(k),default)
    def ang(self,k,default=0):
        v=self.get(k)
        return parse_angle(v) if v is not None else default
    def has(self,k):
        self.get(k)
        return k in self.params
    def invalid(self,k,reason=''):
