"""Numerical map projections, implemented independently with the Python standard library."""
import math
import re
import json
from pathlib import Path

PI = math.pi
HALFPI = PI / 2
DEG = PI / 180
TWOPI = 2 * PI
INF = float('inf')

class InitError(Exception):
    def __init__(self, message, code=1027):
        self.message, self.code = message, code

class CoordinateError(Exception):
    def __init__(self, message=''):
        self.message = message


def adjlon(x):
    if abs(x) <= PI:
        return x
    return (x + PI) % TWOPI - PI


def asqrt(x):
    return math.sqrt(max(0.0, x))


def aasin(x):
    return math.asin(max(-1.0, min(1.0, x)))


number_re = re.compile(r'[+-]?(?:(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?|inf(?:inity)?|nan(?:\([^)]*\))?)', re.I)
angle_number_re = re.compile(r'(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?')


def strtod(s, pos=0):
    start = pos
    while pos < len(s) and s[pos].isspace(): pos += 1
    m = number_re.match(s, pos)
    if not m: return 0.0, start
    try: v = float(m.group())
    except ValueError: v = float('nan')
    return v, m.end()


def angle(s, pos=0):
    """Read a degree/minute/second angle (or an explicitly radian angle)."""
    while pos < len(s) and s[pos].isspace(): pos += 1
    sign = 1
    if pos < len(s) and s[pos] in '+-':
        if s[pos] == '-': sign = -1
        pos += 1
    values, unit, val = [], 0, 0.0
    m = angle_number_re.match(s, pos)
    if m:
        val = float(m.group()); pos = m.end()
    if pos < len(s) and s[pos] in 'rR':
        pos += 1
        return sign*val, pos
    if pos < len(s) and s[pos] in "dD'\"":
        c = s[pos]; pos += 1
        unit = {'d':0, 'D':0, "'":1, '"':2}[c]
        values.append(val / (60**unit))
        while unit < 2:
            m = angle_number_re.match(s, pos)
            if not m: break
            v = float(m.group()); pos = m.end(); unit += 1
            if pos < len(s) and s[pos] in "'\"":
