                pos += 1
            values.append(v / (60**unit))
        val = sum(values)
    if pos < len(s) and s[pos] in 'NnEeSsWw':
        sign = -1 if s[pos] in 'SsWw' else 1
        pos += 1
    return sign*val*DEG, pos


