VERSION='Rel. 9.9.0, September 15th, 2026\n'
CAUSES={1025:'Invalid PROJ string syntax',1026:'Missing argument',1027:'Invalid value for an argument',1028:'Mutually exclusive arguments',1029:'File not found or invalid',2:'Unknown error (code 2)'}

class CliError(Exception):
    def __init__(self,message,code=1,prefix=''):
        self.message,self.code,self.prefix=message,code,prefix


def format_number(fmt,v):
    try: return fmt % v
    except (ValueError,TypeError,OverflowError): return 'nan' if math.isnan(v) else str(v)


def dms(v,positive='',negative='',precision=3,fixed=False):
    if math.isnan(v): return '-2147483648d-2147483648\'nan"'+positive
    neg=v<0
    suffix=negative if neg else positive
    sign='-' if neg and not negative else ''
    if precision>8: precision=3
    factor=10**precision
    seconds=math.floor(abs(v)*3600*factor+.5)/factor
    deg=int(seconds/3600); seconds-=deg*3600
    mins=int(seconds/60); seconds-=mins*60
    seconds=round(seconds,precision)
    if seconds>=60: seconds-=60; mins+=1
    if mins>=60: mins-=60; deg+=1
    if fixed:
        sec=f'{seconds:0{3+precision if precision else 2}.{precision}f}'
        return f'{sign}{deg}d{mins:02d}\'{sec}"{suffix}'
    sec=f'{seconds:.{precision}f}'
    if precision: sec=sec.rstrip('0').rstrip('.')
    result=f'{sign}{deg}d'
    if seconds: result+=f'{mins}\'{sec}"'
    elif mins: result+=f'{mins}\''
    return result+suffix

