#!/usr/bin/env python3
"""A standalone cartographic projection command line interface."""
import sys
import os
import math
import re
import struct
import json
from pathlib import Path
from cartography import Projection, InitError, CoordinateError, DEG, HALFPI, PI, INF, angle, strtod, cfloat, adjlon, UNITS

DATA=Path(__file__).resolve().parent/'data'
DESCRIPTIONS=json.loads((DATA/'projections.json').read_text())
CRS_DEFINITIONS=json.loads((DATA/'crs.json').read_text())
VERSION='Rel. 9.9.0, September 15th, 2026\n'
CAUSES={1025:'Invalid PROJ string syntax',1026:'Missing argument',1027:'Invalid value for an argument',1028:'Mutually exclusive arguments',1029:'File not found or invalid',2:'Unknown error (code 2)'}

class CliError(Exception):
    def __init__(self,message,code=1,prefix=''):
        self.message,self.code,self.prefix=message,code,prefix


def format_number(fmt,v):
    try: return fmt % v
    except (ValueError,TypeError,OverflowError): return 'nan' if math.isnan(v) else str(v)


def dms(v,positive='',negative='',precision=3,fixed=False):
    if math.isnan(v): return '-2147483648d-2147483648\'nan"'+positive
    neg=v<0
    suffix=negative if neg else positive
    sign='-' if neg and not negative else ''
    if precision>8: precision=3
    factor=10**precision
    seconds=math.floor(abs(v)*3600*factor+.5)/factor
    deg=int(seconds/3600); seconds-=deg*3600
    mins=int(seconds/60); seconds-=mins*60
    seconds=round(seconds,precision)
    if seconds>=60: seconds-=60; mins+=1
    if mins>=60: mins-=60; deg+=1
    if fixed:
        sec=f'{seconds:0{3+precision if precision else 2}.{precision}f}'
        return f'{sign}{deg}d{mins:02d}\'{sec}"{suffix}'
    sec=f'{seconds:.{precision}f}'
    if precision: sec=sec.rstrip('0').rstrip('.')
    result=f'{sign}{deg}d'
    if seconds: result+=f'{mins}\'{sec}"'
    elif mins: result+=f'{mins}\''
    return result+suffix

class Pipeline:
    def __init__(self,tokens,default=True):
        ts=[t.lstrip('+') for t in tokens]
        parts=[]; globals=[]; current=None
        for t in ts:
            if t=='step':
                if current is not None: parts.append(current)
                current=[]
            elif current is not None: current.append(t)
            elif not t.startswith('proj='): globals.append(t)
        if current is not None: parts.append(current)
        if not parts: raise InitError('',1025)
        self.steps=[]; self.tokens=ts; self.name='pipeline'; self.used=set(t.split('=')[0] for t in ts)
        for part in parts:
            args=part+globals
            params={}
            for t in args:
                k,_,v=t.partition('='); params.setdefault(k,v)
            name=params.get('proj','')
            inv='inv' in params
            if name in ['unitconvert','axisswap','affine','noop','push','pop','set']:
                pr=None
            else: pr=make_projection(args,default)
            self.steps.append((name,params,pr,inv))
        self.angular_input=self.step_input(self.steps[0]); self.angular_output=self.step_output(self.steps[-1]); self.no_inverse=False
        self.a=6378137; self.es=.00669438002290; self.lat0=0; self.lon0=0; self.pm=0; self.over=False
        for _,_,p,_ in self.steps:
            if p is not None: self.a=p.a; self.es=p.es; break
    def step_input(self,step):
        n,p,pr,i=step
        if pr: return pr.angular_output if i else pr.angular_input
        return n=='unitconvert' and p.get('xy_out' if i else 'xy_in')=='rad'
    def step_output(self,step):
        n,p,pr,i=step
        if pr: return pr.angular_input if i else pr.angular_output
        return n=='unitconvert' and p.get('xy_in' if i else 'xy_out')=='rad'
    def apply(self,x,y,inverse=False):
        steps=reversed(self.steps) if inverse else self.steps
        for name,p,pr,inv in steps:
            ii=inv^inverse
            if pr:
                x,y=pr.inverse(x,y) if ii else pr.forward(x,y)
            elif name=='unitconvert':
                a=UNITS.get(p.get('xy_in','m'),1); b=UNITS.get(p.get('xy_out','m'),1); f=a/b
                if ii: f=1/f
                x*=f; y*=f
            elif name=='axisswap':
                order=p.get('order','1,2').split(','); vals=[x,y,0,0]
                try:
                    if ii:
                        v=[0,0,0,0]
                        for i,s in enumerate(order): j=int(s); v[abs(j)-1]=math.copysign(1,j)*vals[i]
                        x,y=v[:2]
                    else: x,y=[vals[abs(int(s))-1]*(1 if int(s)>0 else -1) for s in order[:2]]
                except (ValueError,IndexError): raise CoordinateError()
            elif name=='affine':
                a=cfloat(p.get('s11'),1); b=cfloat(p.get('s12'),0); c=cfloat(p.get('s21'),0); d=cfloat(p.get('s22'),1); ox=cfloat(p.get('xoff'),0); oy=cfloat(p.get('yoff'),0)
                if ii:
                    x-=ox; y-=oy; det=a*d-b*c; x,y=(d*x-b*y)/det,(a*y-c*x)/det
                else: x,y=a*x+b*y+ox,c*x+d*y+oy
