    def forward(self,x,y): return self.apply(x,y)
    def inverse(self,x,y): return self.apply(x,y,True)


def make_projection(tokens,default=True):
    toks=[t.lstrip('+') for t in tokens]
    params={}
    for t in toks:
        k,_,v=t.partition('='); params.setdefault(k,v)
    name=params.get('proj','')
    if name=='pipeline':
        p=Pipeline(toks,default)
        if len(p.steps)==1 and p.steps[0][2] and not p.steps[0][3]: return p.steps[0][2]
        return p
    if not name:
        if 'init' in params:
            if params['init'].lower().startswith('epsg:'):
                raise CliError("can't initialize operations that take non-angular input coordinates. Try cct.",3)
            raise InitError('init=... syntax not supported in non-PROJ4 emulation mode',1025)
        raise InitError('',2)
    if name not in DESCRIPTIONS and name not in ['latlong','longlat']:
        raise InitError('Unknown projection')
    return Projection(toks,default)


def parse_crs(text):
    t=text.upper()
    if t in CRS_DEFINITIONS: return make_projection(CRS_DEFINITIONS[t].split(),False)
    # The two standard UTM hemispheres and common regional UTM ellipsoids.
    m=re.fullmatch(r'EPSG:(\d+)',t)
