        ell={326:'WGS84',327:'WGS84',258:'GRS80',269:'GRS80',267:'clrk66',230:'intl',283:'GRS80',323:'WGS72',322:'WGS72'}.get(series)
        if ell and 1<=zone<=60:
            return make_projection(['proj=utm','zone='+str(zone)]+(['south'] if series in [327,323,283] else [])+['ellps='+ell],False)
        if code in [4326,4269,4267,4978,4979,4258,4230,4277,4807,4047]:
