            if p.angular_output: raise CliError('CRS must be projected',3)
            return p
        except InitError: pass
    if t in ['WGS84','WGS 84','NAD83','NAD27','OGC:CRS84']:
        raise CliError('CRS must be projected',3)
    if ':' in text:
        prefix=f'proj_create: crs not found: {text}\n'
    else: prefix='proj_create: unrecognized format / unknown name\n'
    raise CliError('CRS is not parseable',3,prefix)

class Options:
    def __init__(self):
        self.inverse=False; self.reverse_input=False; self.reverse_output=False
        self.echo=False; self.verbose=False; self.very_verbose=False; self.factors=False
        self.fmt=None; self.precision=3; self.fixed=False; self.scale=1.0; self.error='*\t*'
        self.tag='#'; self.bin_in=False; self.bin_out=False
        self.tokens=[]; self.files=[]; self.crs=None


def parse_options(args):
    o=Options(); i=0
    while i<len(args):
        arg=args[i]; i+=1
        if arg.startswith('+'):
            o.tokens.append(arg)
        elif arg.startswith('-') and len(arg)>1:
            j=1
            while j<len(arg):
                c=arg[j]; j+=1
                if c=='l':
                    mode=arg[j:j+1]
                    if mode=='=':
                        n=arg[j+1:]
                        if n in ['latlong','longlat']: n='lonlat'
                        if n in DESCRIPTIONS: sys.stdout.write(f'{n:>9s} : '+DESCRIPTIONS[n]+'\n')
                    elif mode in ['','p','P']:
                        for name,desc in DESCRIPTIONS.items():
                            sys.stdout.write(name+' : '+(desc if mode=='P' else desc.split('\n')[0])+'\n')
                    elif mode in ['e','u']:
                        sys.stdout.write((DATA/('ellipsoids.txt' if mode=='e' else 'units.txt')).read_text())
                    else: raise CliError('invalid list option: l'+mode)
                    return None
                elif c in 'demf':
                    if i>=len(args): raise CliError('missing argument for -'+c)
                    value=args[i]; i+=1
                    if c=='d':
                        m=re.match(r'\s*[+-]?\d+',value); nd=int(m[0]) if m else 0
                        o.fmt='%.'+str(nd)+'f'
                        # -d consumes the rest of its option word.
                        j=len(arg)
                    elif c=='f': o.fmt=value
                    elif c=='e': o.error=value
                    elif c=='m':
                        if value.startswith(('1:','1/')):
                            t=cfloat(value[2:]); o.scale=1/t if t!=0 else 0
                        else: o.scale=cfloat(value)
                        if o.scale==0: raise CliError('invalid scale argument')
                elif c=='t':
                    if j>=len(arg): raise CliError('missing -t col. 1 tag')
                    o.tag=arg[j]; j+=1
                elif c in ['w','W']:
                    if j>=len(arg) or not arg[j].isdigit(): raise CliError('-W argument missing or non-digit')
                    p=int(arg[j]);j+=1
                    if p<=8: o.precision=p
                    o.fixed=(c=='W')
                elif c=='I': o.inverse=True
                elif c=='r': o.reverse_input=True
                elif c=='s': o.reverse_output=True
                elif c=='E': o.echo=True
                elif c=='S': o.factors=True
                elif c=='v': o.verbose=True
                elif c=='V': o.verbose=True; o.very_verbose=True; o.factors=True
                elif c=='i': o.bin_in=True
                elif c=='o': o.bin_out=True
                elif c=='b': o.bin_in=True;o.bin_out=True
                else: raise CliError('invalid option: -'+c)
        else: o.files.append(arg)
    if not o.tokens and o.files:
        o.crs=o.files.pop(0)
    if o.fmt is not None and not re.fullmatch(r'%[-+ #0]*\d*(?:\.\d+)?[eEfFgG]',o.fmt):
        raise CliError('invalid format string',3)
    return o


def wrap_params(tokens):
    result=''; line='#'
    for token in tokens:
        t=' +'+token
        if len(line)+len(t)>77 and len(line)>1:
            result+=line+'\n'; line='#'
        line+=t
    if len(line)>1: result+=line+'\n'
    return result


def verbose_header(p,o):
    name=p.name
    if name in ['longlat','latlong']: name='lonlat'
    desc=DESCRIPTIONS.get(name,name)
    out=''.join('#'+line+'\n' for line in desc.split('\n'))
    if isinstance(p,Pipeline):
        out+=wrap_params(p.tokens)
    else:
        used=[]; unused=[]; seen=set()
        for token in p.tokens:
            k=token.partition('=')[0]
            if k in p.used and k not in seen:
                used.append(token); seen.add(k)
            else: unused.append(token)
        out+=wrap_params(used)
        if unused: out+='#--- following specified but NOT used\n'+wrap_params(unused)
    if o.very_verbose:
        fmt=o.fmt or '%.3f'
        if p.es==0:
            out+='#Final Earth figure: sphere\n#  Radius: '+format_number(fmt,p.a)+'\n'
        else:
            invf=1/(1-math.sqrt(1-p.es))
            out+='#Final Earth figure: ellipsoid\n#  Major axis (a): '+format_number(fmt,p.a)+'\n'
            out+='#  1/flattening: %.6f\n#  squared eccentricity: %.12f\n'%(invf,p.es)
    return out


def factors(p,lon,lat):
    if isinstance(p,Pipeline):
        pr=next((s[2] for s in p.steps if s[2]),None)
        if pr: return factors(pr,lon,lat)
        raise CoordinateError()
    if abs(lat)>HALFPI+1e-12: raise CoordinateError('Invalid latitude')
    if abs(lon)>10: raise CoordinateError('Invalid longitude')
    lp=adjlon(lon-p.lon0-p.pm)
    h=1e-5
    lat=max(-HALFPI+h,min(HALFPI-h,lat))
    # Four corner, central finite differences, matching the documented numerical factors.
    pp=p.raw_forward(lp+h,lat+h); pm=p.raw_forward(lp+h,lat-h)
    mp=p.raw_forward(lp-h,lat+h); mm=p.raw_forward(lp-h,lat-h)
    x_l=(pp[0]+pm[0]-mp[0]-mm[0])/(4*h)
    y_l=(pp[1]+pm[1]-mp[1]-mm[1])/(4*h)
    x_p=(pp[0]-pm[0]+mp[0]-mm[0])/(4*h)
    y_p=(pp[1]-pm[1]+mp[1]-mm[1])/(4*h)
    cos=math.cos(lat); es=p.es
    t=1-es*math.sin(lat)**2
    rr=t*t/(1-es)
    mer=math.hypot(x_p,y_p)*t**1.5/(1-es)
    par=math.hypot(x_l,y_l)*math.sqrt(t)/cos
    area=(y_p*x_l-x_p*y_l)*rr/cos
    theta=math.asin(max(-1,min(1,area/(mer*par)))) if mer*par else 0
    conv=-math.atan2(x_p,y_p)
    t0=mer*mer+par*par
    a=math.sqrt(max(0,t0+2*area)); b=math.sqrt(max(0,t0-2*area))
    maj=(a+b)/2; minor=(a-b)/2
    w=2*math.asin(max(-1,min(1,(maj-minor)/(maj+minor)))) if maj+minor else 0
    return mer,par,area,w/DEG,maj,minor,theta/DEG,conv/DEG


def very_verbose(o,p,lon,lat,x,y,f,trailing):
    out=trailing+'\n' if trailing else ''
    out+='Longitude: '+dms(lon/DEG,'E','W',o.precision,o.fixed)+' [ %.11g ]\n'%(lon/DEG)
    out+='Latitude:  '+dms(lat/DEG,'N','S',o.precision,o.fixed)+' [ %.11g ]\n'%(lat/DEG)
    fmt=o.fmt or '%.2f'
    out+='Easting (x):   '+format_number(fmt,x)+'\nNorthing (y):  '+format_number(fmt,y)+'\n'
    h,k,s,w,a,b,theta,conv=f
    out+='Meridian scale (h) : %.8f  ( %.4g %% error )\n'%(h,(h-1)*100)
    out+='Parallel scale (k) : %.8f  ( %.4g %% error )\n'%(k,(k-1)*100)
    out+='Areal scale (s):     %.8f  ( %.4g %% error )\n'%(s,(s-1)*100)
    out+='Angular distortion (w): %.3f\nMeridian/Parallel angle: %.5f\n'%(w,theta)
    out+='Convergence : '+dms(conv,'','',o.precision,o.fixed)+' [ %.8f ]\n'%conv
    out+='Max-min (Tissot axis a-b) scale error: %.5f %.5f\n\n'%(a,b)
    return out


def init_projection(o):
    try:
        p=parse_crs(o.crs) if o.crs is not None else make_projection(o.tokens)
    except InitError as e:
        cause=CAUSES.get(e.code,'Invalid value for an argument')
        if e.code==2: prefix='proj_create: unrecognized format / unknown name\n'
        else: prefix=f'proj_create: Error {e.code} ({cause})'+(': '+e.message if e.message else '')+'\n'
        raise CliError('projection initialization failure\ncause: '+cause,3,prefix)
    if not p.angular_input:
        raise CliError("can't initialize operations that take non-angular input coordinates. Try cct.",3)
    if p.angular_output:
        raise CliError("can't initialize operations that produce angular output coordinates",3)
    if o.inverse and p.no_inverse: raise CliError('inverse projection not available',3)
    return p


def process_record(o,p,first,second,echo='',trailing='',filename='<stdin>',line=1):
    if o.reverse_input: first,second=second,first
    failed=False; ff=None
    lon,lat=first,second; x=y=INF
    try:
        if o.inverse:
            x=first/o.scale; y=second/o.scale
            lon,lat=p.inverse(x,y)
            out1=lon/DEG; out2=lat/DEG
        else:
            x,y=p.forward(lon,lat)
            x*=o.scale;y*=o.scale
            out1,out2=x,y
    except (CoordinateError,ValueError,OverflowError,ZeroDivisionError) as err:
        if isinstance(err,CoordinateError) and err.message:
            sys.stderr.write(p.name+': '+err.message+'\n')
        failed=True;out1=out2=INF
    if o.factors:
        try:
            ff=factors(p,lon,lat)
        except (CoordinateError,ValueError,ZeroDivisionError,OverflowError) as err:
            if not o.very_verbose and isinstance(err,CoordinateError) and err.message:
                sys.stderr.write(p.name+': '+err.message+'\n')
    if o.very_verbose:
        if failed or ff is None:
            sys.stderr.write(VERSION+f'<{PROGRAM}>: while processing file: {filename}, line {line}\nInvalid coordinate\n')
            return ''
        return very_verbose(o,p,lon,lat,x,y,ff,trailing)
    if o.bin_out:
        if o.inverse: out1=lon; out2=lat
        if o.reverse_output: out1,out2=out2,out1
        return struct.pack('=dd',out1,out2)
    if failed:
        result=o.error
    elif o.inverse and o.fmt is None:
        a=dms(out1,'E','W',o.precision,o.fixed);b=dms(out2,'N','S',o.precision,o.fixed)
        result=b+'\t'+a if o.reverse_output else a+'\t'+b
    else:
        fmt=o.fmt or '%.2f'
        if o.reverse_output: out1,out2=out2,out1
        result=format_number(fmt,out1)+'\t'+format_number(fmt,out2)
    if o.echo: result=echo+'\t'+result
    if o.factors:
        if ff is None or failed: result+='\t<* * * * * *>'
        else: result+='\t<'+' '.join('%.6g'%v for v in ff[:6])+'>'
    return result+trailing+'\n'


def process_stream(stream,filename,o,p):
    if o.bin_in:
        lineno=0
        while True:
            data=stream.read(16)
            if len(data)!=16: break
            lineno+=1
            x,y=struct.unpack('=dd',data)
            # Binary geographic input/output uses radians.
            result=process_record(o,p,x,y,filename=filename,line=lineno)
            write_result(result)
        return
    count=0
    # The original interface processes a maximum 999 characters at a time.
    while True:
        data=stream.readline(1000)
        if not data: break
        count+=1
        text=data.decode('utf-8','surrogateescape') if isinstance(data,bytes) else data
        if text.startswith(o.tag):
            if not o.bin_out: sys.stdout.write(text)
            continue
        text=text.split('\x00')[0]
        # Strip only the record delimiter, leaving all trailing fields unchanged.
        if text.endswith('\n'): text=text[:-1]
        parse=strtod if o.inverse else angle
        a,pos=parse(text,0);b,end=parse(text,pos)
        echo=text[:end];trailing=text[end:]
        result=process_record(o,p,a,b,echo,trailing,filename,count)
        write_result(result)


def write_result(result):
    if isinstance(result,bytes):
        sys.stdout.flush(); sys.stdout.buffer.write(result)
    else: sys.stdout.write(result)

PROGRAM=os.path.basename(sys.argv[0])

def main():
    args=sys.argv[1:]
    if not args:
        sys.stderr.write(VERSION+f'usage: {PROGRAM} [-bdeEfiIlmorsStTvVwW [args]] [+opt[=arg] ...] [file ...]\n')
        return 0
    try:
        o=parse_options(args)
        if o is None: return 0
        if PROGRAM.startswith('inv'): o.inverse=True
        p=init_projection(o)
        if o.verbose: sys.stdout.write(verbose_header(p,o))
        files=o.files or ['-']
        for fn in files:
            if fn=='-':
                stream=sys.stdin.buffer;name='<stdin>'
            else:
                try: stream=open(fn,'rb'); name=fn
                except OSError as e:
                    sys.stderr.write(VERSION+f'<{PROGRAM}>: \nSys errno: {e.errno}: {e.strerror}\ninput file: {fn}\n')
                    continue
            try: process_stream(stream,name,o,p)
            except IsADirectoryError: pass
            if fn!='-': stream.close()
        return 0
    except CliError as e:
        sys.stderr.write(e.prefix+VERSION+f'<{PROGRAM}>: \n'+e.message+'\nprogram abnormally terminated\n')
        return e.code
    except BrokenPipeError:
        return 0

if __name__=='__main__':
    sys.exit(main())
